        old.close().await;
        let ctx = context(path_string);
        assert_eq!(db_read(&ctx, "legacy").await.unwrap(), Some(vec![0, 255, 65]));
        assert_eq!(db_read(&ctx, "missing").await.unwrap(), None);
        db_write(&ctx, "persisted", &[0, 128, 255]).await.unwrap();
        db_write(&ctx, "legacy", b"updated").await.unwrap();
        assert_eq!(db_read(&ctx, "legacy").await.unwrap(), Some(b"updated".to_vec()));
        db_remove(&ctx, "legacy").await.unwrap();
        assert_eq!(db_read(&ctx, "legacy").await.unwrap(), None);
        ctx.get(DATABASE).close().await;
        let reopened = context(path_string);
        assert_eq!(db_read(&reopened, "persisted").await.unwrap(), Some(vec![0, 128, 255]));
        reopened.get(DATABASE).close().await;
        std::fs::remove_file(path).unwrap();
    }

    #[tokio::test]
    async fn sqlite_lazy_schema_waiter_observes_write() {
        let ctx = context(":memory:");
        let waiting = db_read_or_wait(&ctx, "wake");
        let writing = async {
            tokio::time::sleep(Duration::from_millis(10)).await;
            db_write(&ctx, "wake", b"ready").await.unwrap();
        };
        let (value, ()) = tokio::time::timeout(Duration::from_secs(2), async {
            tokio::join!(waiting, writing)
        }).await.expect("SQLite waiter was not notified");
        assert_eq!(value.unwrap(), b"ready");
        ctx.get(DATABASE).close().await;
    }
}

#[cfg(test)]
mod slipstream_sqlite_cancellation_tests {
    //! Deterministic SQLite cancellation qualification; no broker/client start.
    use crate::{
        Config,
        database::{DATABASE, db_read, db_read_or_wait, db_remove, db_write},
    };
    use anyctx::AnyCtx;
    use std::{path::PathBuf, sync::mpsc, time::Duration};

    fn context(path: &PathBuf) -> AnyCtx<Config> {
        AnyCtx::new(
            serde_json::from_value(serde_json::json!({
                "exit_constraint":"auto", "cache":path,
                "credentials":{"secret":"public-synthetic-sqlite-only"}
            }))
            .unwrap(),
        )
    }
    fn fresh(name: &str) -> (AnyCtx<Config>, PathBuf) {
        let path = std::env::temp_dir().join(format!(
            "queued-{}-{}-{}.sqlite",
            name,
            std::process::id(),
            rand::random::<u64>()
        ));
        (context(&path), path)
    }
    async fn pause_next_statement(
        ctx: &AnyCtx<Config>,
    ) -> (tokio::sync::oneshot::Receiver<()>, mpsc::Sender<()>) {
        let mut connection = ctx.get(DATABASE).acquire().await.unwrap();
        let (entered, receiver) = tokio::sync::oneshot::channel();
        let (release, wait_release) = mpsc::channel();
        let mut entered = Some(entered);
        connection
            .lock_handle()
            .await
            .unwrap()
            .set_progress_handler(1, move || {
                if let Some(entered) = entered.take() {
                    entered.send(()).unwrap();
                    // Real SQLite worker is inside sqlite3_step/prepare. No sleeps infer entry.
                    return wait_release.recv_timeout(Duration::from_secs(30)).is_ok();
                }
                true
            });
        connection.return_to_pool().await;
        (receiver, release)
    }
    async fn entered(receiver: tokio::sync::oneshot::Receiver<()>) {
        tokio::time::timeout(Duration::from_secs(10), receiver)
            .await
            .unwrap()
            .unwrap();
    }
    async fn valid_and_close(ctx: &AnyCtx<Config>) {
        let result: String = sqlx::query_scalar("PRAGMA integrity_check")
            .fetch_one(ctx.get(DATABASE))
            .await
            .unwrap();
        assert_eq!(result, "ok");
        tokio::time::timeout(Duration::from_secs(5), ctx.get(DATABASE).close())
            .await
            .unwrap();
    }
    async fn parked<F: std::future::Future>(ctx: &AnyCtx<Config>, mut waiting: std::pin::Pin<&mut F>) {
        tokio::time::timeout(Duration::from_secs(5), async {
            loop {
                assert!(futures_util::poll!(waiting.as_mut()).is_pending());
                // The SELECT returned None and its lease was returned. The future
                // is now parked on EVENT, not waiting for the database connection.
                if ctx.get(DATABASE).num_idle() == 1 {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .unwrap();
    }
    #[tokio::test]
    async fn queued_cancel_releases_middle_waiter_and_preserves_cache() {
        let (ctx, path) = fresh("pool");
        db_write(&ctx, "legacy", &[0, 128, 255]).await.unwrap();
        let held = ctx.get(DATABASE).acquire().await.unwrap();
        let mut first = Box::pin(db_write(&ctx, "first", b"one"));
        let mut cancelled = Box::pin(db_write(&ctx, "cancelled", b"never"));
        let mut last = Box::pin(db_write(&ctx, "last", b"three"));
        assert!(futures_util::poll!(first.as_mut()).is_pending());
        assert!(futures_util::poll!(cancelled.as_mut()).is_pending());
        assert!(futures_util::poll!(last.as_mut()).is_pending());
        drop(cancelled);
        drop(held);
        tokio::time::timeout(Duration::from_secs(5), async {
            tokio::try_join!(first, last).unwrap();
        })
        .await
        .unwrap();
        assert_eq!(db_read(&ctx, "cancelled").await.unwrap(), None);
        assert_eq!(db_read(&ctx, "first").await.unwrap(), Some(b"one".to_vec()));
        assert_eq!(
            db_read(&ctx, "last").await.unwrap(),
            Some(b"three".to_vec())
        );
        valid_and_close(&ctx).await;
        let reopened = context(&path);
        assert_eq!(
            db_read(&reopened, "legacy").await.unwrap(),
            Some(vec![0, 128, 255])
        );
        assert_eq!(db_read(&reopened, "cancelled").await.unwrap(), None);
        valid_and_close(&reopened).await;
    }
    #[tokio::test]
    async fn running_cancel_hands_connection_to_next_writer_without_stale_lock() {
        let (ctx, path) = fresh("running");
        db_write(&ctx, "legacy", b"unchanged").await.unwrap();
        let (barrier, release) = pause_next_statement(&ctx).await;
        let copy = ctx.clone();
        let running = tokio::spawn(async move { db_write(&copy, "running", b"submitted").await });
        entered(barrier).await;
        let mut queued = Box::pin(db_write(&ctx, "successor", b"next"));
        assert!(futures_util::poll!(queued.as_mut()).is_pending());
        running.abort();
        assert!(running.await.unwrap_err().is_cancelled());
        release.send(()).unwrap();
        tokio::time::timeout(Duration::from_secs(5), queued)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            db_read(&ctx, "running").await.unwrap(),
            Some(b"submitted".to_vec()),
            "cancellation after submission is not rollback"
        );
        assert_eq!(
            db_read(&ctx, "successor").await.unwrap(),
            Some(b"next".to_vec())
        );
        valid_and_close(&ctx).await;
        let reopened = context(&path);
        assert_eq!(
            db_read(&reopened, "legacy").await.unwrap(),
            Some(b"unchanged".to_vec())
        );
        assert_eq!(
            db_read(&reopened, "successor").await.unwrap(),
            Some(b"next".to_vec())
        );
        valid_and_close(&reopened).await;
    }
    #[tokio::test]
    async fn cancelled_submitted_write_wakes_existing_cache_waiter() {
        let (ctx, _) = fresh("notification");
        assert_eq!(db_read(&ctx, "late").await.unwrap(), None);
        let mut waiting = Box::pin(db_read_or_wait(&ctx, "late"));
        parked(&ctx, waiting.as_mut()).await;
        let (barrier, release) = pause_next_statement(&ctx).await;
        let copy = ctx.clone();
        let running =
            tokio::spawn(async move { db_write(&copy, "late", b"committed-after-cancel").await });
        entered(barrier).await;
        running.abort();
        assert!(running.await.unwrap_err().is_cancelled());
        // The drop guard has fired while the native worker remains paused. Poll
        // the reader now: it must queue behind that worker, never return old data.
        assert!(futures_util::poll!(waiting.as_mut()).is_pending());
        assert_eq!(ctx.get(DATABASE).num_idle(), 0);
        release.send(()).unwrap();
        // Both queued reads must continue being polled: parking a selected pool
        // acquire while awaiting the other reader would deadlock the test itself.
        let (observed, wake) = tokio::join!(
            tokio::time::timeout(Duration::from_secs(5), db_read(&ctx, "late")),
            tokio::time::timeout(Duration::from_secs(1), waiting)
        );
        valid_and_close(&ctx).await;
        assert_eq!(
            observed.unwrap().unwrap(),
            Some(b"committed-after-cancel".to_vec())
        );
        assert_eq!(
            wake.expect("committed SQLite write lost EVENT notification after caller cancellation")
                .unwrap(),
            b"committed-after-cancel"
        );
    }

    #[tokio::test]
    async fn cancelled_before_acquire_does_not_publish_or_strand_waiter() {
        let (ctx, path) = fresh("pre-acquire");
        assert_eq!(db_read(&ctx, "late").await.unwrap(), None);
        let mut waiting = Box::pin(db_read_or_wait(&ctx, "late"));
        parked(&ctx, waiting.as_mut()).await;
        let mut held = ctx.get(DATABASE).acquire().await.unwrap();
        let mut cancelled = Box::pin(db_write(&ctx, "late", b"must-not-commit"));
        assert!(futures_util::poll!(cancelled.as_mut()).is_pending());
        drop(cancelled);
        assert!(futures_util::poll!(waiting.as_mut()).is_pending());
        held.return_to_pool().await;
        parked(&ctx, waiting.as_mut()).await;
        assert_eq!(db_read(&ctx, "late").await.unwrap(), None);
        db_write(&ctx, "late", b"later-success").await.unwrap();
        assert_eq!(
            tokio::time::timeout(Duration::from_secs(5), waiting)
                .await
                .unwrap()
                .unwrap(),
            b"later-success"
        );
        valid_and_close(&ctx).await;
        let reopened = context(&path);
        assert_eq!(
            db_read(&reopened, "late").await.unwrap(),
            Some(b"later-success".to_vec())
        );
        valid_and_close(&reopened).await;
    }

    #[tokio::test]
    async fn cancelled_after_commit_before_caller_resume_wakes_waiter() {
        let (ctx, path) = fresh("after-commit");
        assert_eq!(db_read(&ctx, "late").await.unwrap(), None);
        let mut waiting = Box::pin(db_read_or_wait(&ctx, "late"));
        parked(&ctx, waiting.as_mut()).await;
        let (mut barrier, release) = pause_next_statement(&ctx).await;
        let mut write = Box::pin(db_write(&ctx, "late", b"already-committed"));
        tokio::time::timeout(Duration::from_secs(5), async {
            loop {
                assert!(futures_util::poll!(write.as_mut()).is_pending());
                if barrier.try_recv().is_ok() {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .unwrap();
        release.send(()).unwrap();
        // Do not poll the caller again. An independent connection proves commit
        // while the original future still owns the lease and has not returned.
        let observer = context(&path);
        tokio::time::timeout(Duration::from_secs(5), async {
            loop {
                if db_read(&observer, "late").await.unwrap() == Some(b"already-committed".to_vec()) {
                    break;
                }
                tokio::task::yield_now().await;
            }
        })
        .await
        .unwrap();
        assert!(futures_util::poll!(waiting.as_mut()).is_pending());
        drop(write);
        assert_eq!(
            tokio::time::timeout(Duration::from_secs(5), waiting)
                .await
                .unwrap()
                .unwrap(),
            b"already-committed"
        );
        valid_and_close(&observer).await;
        valid_and_close(&ctx).await;
    }

    async fn rejected_sql_does_not_publish_or_strand_waiter(action: &str) {
        let (ctx, path) = fresh(action);
        db_write(&ctx, "legacy", &[0, 128, 255]).await.unwrap();
        let trigger = format!(
            "CREATE TRIGGER reject_fixture BEFORE INSERT ON misc WHEN NEW.key = 'late' BEGIN INSERT INTO misc VALUES ('side-effect', X'01'); SELECT RAISE({}, 'fixture rejected'); END",
            action
        );
        sqlx::query(&trigger)
            .execute(ctx.get(DATABASE))
            .await
            .unwrap();
        let mut waiting = Box::pin(db_read_or_wait(&ctx, "late"));
        parked(&ctx, waiting.as_mut()).await;
        let failure = db_write(&ctx, "late", b"rejected").await.unwrap_err();
        assert!(failure.to_string().contains("fixture rejected"));
        parked(&ctx, waiting.as_mut()).await;
        assert_eq!(db_read(&ctx, "late").await.unwrap(), None);
        assert_eq!(db_read(&ctx, "side-effect").await.unwrap(), None);
        assert_eq!(
            db_read(&ctx, "legacy").await.unwrap(),
            Some(vec![0, 128, 255])
        );
        sqlx::query("DROP TRIGGER reject_fixture")
            .execute(ctx.get(DATABASE))
            .await
            .unwrap();
        db_write(&ctx, "late", b"retry-committed").await.unwrap();
        assert_eq!(
            tokio::time::timeout(Duration::from_secs(5), waiting)
                .await
                .unwrap()
                .unwrap(),
            b"retry-committed"
        );
        valid_and_close(&ctx).await;
        let reopened = context(&path);
        assert_eq!(
            db_read(&reopened, "late").await.unwrap(),
            Some(b"retry-committed".to_vec())
        );
        assert_eq!(db_read(&reopened, "side-effect").await.unwrap(), None);
        valid_and_close(&reopened).await;
    }
    #[tokio::test]
    async fn sql_error_wakes_only_for_committed_retry() {
        rejected_sql_does_not_publish_or_strand_waiter("ABORT").await;
    }
    #[tokio::test]
    async fn sql_rollback_wakes_only_for_committed_retry() {
        rejected_sql_does_not_publish_or_strand_waiter("ROLLBACK").await;
    }

    #[tokio::test]
    async fn cancelled_remove_notifies_after_native_side_effect_commit() {
        let (ctx, _) = fresh("remove");
        db_write(&ctx, "remove-me", b"original").await.unwrap();
        // Controlled trigger makes a removal's notification observable to the
        // public db_read_or_wait API without exposing EVENT as a test-only API.
        sqlx::query("CREATE TRIGGER deletion_fixture AFTER DELETE ON misc BEGIN INSERT INTO misc VALUES ('removed', X'00FF'); END").execute(ctx.get(DATABASE)).await.unwrap();
        let mut waiting = Box::pin(db_read_or_wait(&ctx, "removed"));
        parked(&ctx, waiting.as_mut()).await;
        let (barrier, release) = pause_next_statement(&ctx).await;
        let copy = ctx.clone();
        let removing = tokio::spawn(async move { db_remove(&copy, "remove-me").await });
        entered(barrier).await;
        removing.abort();
        assert!(removing.await.unwrap_err().is_cancelled());
        assert!(futures_util::poll!(waiting.as_mut()).is_pending());
        release.send(()).unwrap();
        let (observed, wake) = tokio::join!(
            db_read(&ctx, "remove-me"),
            tokio::time::timeout(Duration::from_secs(5), waiting)
        );
        assert_eq!(observed.unwrap(), None);
        assert_eq!(wake.unwrap().unwrap(), vec![0, 255]);
        valid_and_close(&ctx).await;
    }
}

